import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        int[] a = new int[n], count = new int[1000001];
        for (int i = 0; i < n; i++) count[a[i] = (int) nextLong()]++;
        // Sort by (frequency, value): both fit in one long key.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = ((long) count[a[i]] << 21) | a[i];
        Arrays.sort(key);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(key[i] & ((1 << 21) - 1)).append(i + 1 < n ? ' ' : '\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	count := make([]int64, 1000001)
	for i := range a {
		a[i] = nextInt()
		count[a[i]]++
	}
	// Sort by (frequency, value): both fit in one int64 key.
	key := make([]int64, n)
	for i, v := range a {
		key[i] = count[v]<<21 | v
	}
	slices.Sort(key)
	w := bufio.NewWriterSize(os.Stdout, 1<<16)
	defer w.Flush()
	for i, k := range key {
		w.WriteString(strconv.FormatInt(k&(1<<21-1), 10))
		if i+1 < n {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
